// Using .eslintrc.js rather than JSON so the exceptions below can carry their
// reasoning — a silenced rule with no explanation is indistinguishable from a
// rule nobody understood.
module.exports = {
  extends: "next/core-web-vitals",

  ignorePatterns: [
    "data/**", // generated by scripts/sync-content.ts
    ".next/**",
    "node_modules/**",
    "*.js",
    "scripts/**", // build-time node scripts, not app code
  ],

  overrides: [
    {
      // OG image routes render through satori, not the DOM. next/image does
      // not exist in that renderer, and alt text is meaningless on an image
      // being rasterised straight to PNG.
      files: ["**/og/route.tsx", "**/opengraph-image.tsx", "**/icon.tsx"],
      rules: {
        "@next/next/no-img-element": "off",
        "jsx-a11y/alt-text": "off",
      },
    },
  ],
};
